use azul::prelude::*;

pub fn render_ui() -> Dom {
    Dom::create_body()
        .with_children(vec![
            Dom::create_h1_with_text("My App"),
            Dom::create_p_with_text("Hello"),
        ])
}

struct AppData {}

extern "C" fn layout(_data: RefAny, _info: LayoutCallbackInfo) -> Dom {
    render_ui()
}

fn main() {
    let app = App::create(RefAny::new(AppData {}), AppConfig::create());
    let mut window = WindowCreateOptions::create(layout);
    window.window_state.title = "My App".into();
    app.run(window);
}
